/* snakeplot.js — recolour + click-selection for the GPCRdb OPRM1 snakeplot.
   The SVG is injected into #snake_container; every residue is a
   <circle class='... rcircle' id='<resnum>'> with a matching <text id='<resnum>t'>.
   Server drives colour (snake_recolor) and highlight (snake_highlight);
   clicks are reported back via input$snake_click. */
(function () {
  "use strict";

  // luminance of a #rrggbb colour -> choose black/white label for contrast
  function labelColor(hex) {
    if (!hex || hex[0] !== "#" || hex.length < 7) return "#000000";
    var r = parseInt(hex.substr(1, 2), 16),
        g = parseInt(hex.substr(3, 2), 16),
        b = parseInt(hex.substr(5, 2), 16);
    var lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
    return lum > 0.6 ? "#000000" : "#ffffff";
  }

  function circles() {
    return document.querySelectorAll("#snake_container circle.rcircle");
  }
  function textFor(id) {
    return document.getElementById(id + "t");
  }
  // Shiny auto-unboxes length-1 vectors to scalars; always work with an array.
  function asArray(v) {
    if (v == null) return [];
    return Array.isArray(v) ? v : [v];
  }

  // current per-residue score values + label, populated by snake_recolor
  var valMap = {};
  var scoreLabel = "";

  // resolve a hovered/clicked element to {id, title} — accepts the residue
  // circle or the label text painted on top of it.
  function resolveResidue(el) {
    if (!el || !el.getAttribute) return null;
    var id = null;
    if (el.tagName === "circle" && el.classList.contains("rcircle")) {
      id = el.getAttribute("id");
    } else if (el.tagName === "text") {
      var tid = el.getAttribute("id");
      if (tid && /^\d+t$/.test(tid)) id = tid.slice(0, -1);
    }
    if (!id || !/^\d+$/.test(id)) return null;
    return { id: id, title: el.getAttribute("original_title") || el.getAttribute("title") || "" };
  }

  // ---- hover tooltip (GPCRdb / Ballesteros-Weinstein number + score) -------
  var tip = null;
  function ensureTip() {
    if (tip) return tip;
    tip = document.createElement("div");
    tip.id = "snake-tooltip";
    tip.style.cssText =
      "position:fixed;z-index:9999;pointer-events:none;display:none;" +
      "background:rgba(33,37,41,0.95);color:#fff;padding:5px 8px;border-radius:5px;" +
      "font:12px/1.35 system-ui,-apple-system,Helvetica,Arial,sans-serif;" +
      "box-shadow:0 2px 8px rgba(0,0,0,.3);max-width:240px;";
    document.body.appendChild(tip);
    return tip;
  }
  function tipHTML(info) {
    // original_title is "<wt><pos> <generic>", e.g. "R167 3.50x50" (generic may be empty)
    var parts = (info.title || "").trim().split(/\s+/);
    var res = parts[0] || ("res " + info.id);
    var gen = parts.slice(1).join(" ");
    var html = "<b>" + res + "</b>";
    html += gen ? "<br>GPCRdb / BW: <b>" + gen + "</b>"
                : "<br><span style='opacity:.7'>no generic number</span>";
    var v = valMap[info.id];
    if (v !== undefined && v !== null && v !== "NA" && scoreLabel)
      html += "<br>" + scoreLabel + ": " + v;
    return html;
  }
  function positionTip(ev) {
    var t = ensureTip(), pad = 14;
    var w = t.offsetWidth, h = t.offsetHeight;
    var x = ev.clientX + pad, y = ev.clientY + pad;
    if (x + w > window.innerWidth) x = ev.clientX - w - pad;
    if (y + h > window.innerHeight) y = ev.clientY - h - pad;
    t.style.left = x + "px";
    t.style.top = y + "px";
  }
  document.addEventListener("mouseover", function (ev) {
    var info = resolveResidue(ev.target);
    if (!info) return;
    var t = ensureTip();
    t.innerHTML = tipHTML(info);
    t.style.display = "block";
    positionTip(ev);
  });
  document.addEventListener("mousemove", function (ev) {
    if (tip && tip.style.display === "block" && resolveResidue(ev.target)) positionTip(ev);
  });
  document.addEventListener("mouseout", function (ev) {
    if (resolveResidue(ev.target) && tip) tip.style.display = "none";
  });

  // ---- click delegation (survives SVG re-render) ---------------------------
  // A residue is a <circle id='N'> with the label <text id='Nt'> painted on top,
  // so accept clicks on either and resolve to the residue number N.
  var suppressClick = false;   // set when a pan drag ends, so it is not a click
  document.addEventListener("click", function (ev) {
    if (suppressClick) { suppressClick = false; return; }
    var el = ev.target;
    if (!el || !el.getAttribute) return;
    var id = null;
    if (el.tagName === "circle" && el.classList.contains("rcircle")) {
      id = el.getAttribute("id");
    } else if (el.tagName === "text") {
      var tid = el.getAttribute("id");
      if (tid && /^\d+t$/.test(tid)) id = tid.slice(0, -1);
    }
    if (!id || !/^\d+$/.test(id)) return;
    if (window.Shiny && Shiny.setInputValue) {
      Shiny.setInputValue("snake_click",
        { id: parseInt(id, 10), nonce: Math.random() },
        { priority: "event" });
    }
  });

  // pointer cursor once the svg is in the DOM
  var cursorObserver = new MutationObserver(function () {
    var cs = circles();
    if (cs.length) {
      cs.forEach(function (c) { c.style.cursor = "pointer"; });
    }
  });
  document.addEventListener("DOMContentLoaded", function () {
    var cont = document.getElementById("snake_container");
    if (cont) cursorObserver.observe(cont, { childList: true, subtree: true });
  });

  // ---- responsive fit + zoom / pan ----------------------------------------
  // The SVG ships with a viewBox, so it already scales to any container.  On
  // top of that we drive the viewBox directly to zoom and pan: base = the
  // tight fit of the drawing, view = what is currently shown.
  var MIN_ZOOM = 0.5, MAX_ZOOM = 12;
  var base = null;      // {x, y, w, h} — the fitted (100 %) view
  var view = null;      // {x, y, w, h} — the current view
  var baseTight = false;   // has base been measured, or is it still the fallback?

  function svgEl() { return document.querySelector("#snake_container svg"); }

  function applyView() {
    var svg = svgEl();
    if (!svg || !view) return;
    svg.setAttribute("viewBox",
      view.x + " " + view.y + " " + view.w + " " + view.h);
  }

  // tighten `base` to the drawing's real bounding box (the baked-in viewBox is
  // a safe superset).  getBBox() only works once the element is laid out, so
  // this is retried until the Snakeplot tab is actually visible.
  function computeBase() {
    var svg = svgEl();
    if (!svg) return false;
    if (!svg.getBoundingClientRect().width) return false;   // tab still hidden
    var bb;
    try { bb = svg.getBBox(); } catch (e) { return false; }
    if (!bb || !bb.width || !bb.height) return false;
    var pad = Math.max(bb.width, bb.height) * 0.01;
    base = { x: bb.x - pad, y: bb.y - pad,
             w: bb.width + 2 * pad, h: bb.height + 2 * pad };
    baseTight = true;
    return true;
  }

  function fit() {
    if (!baseTight && !computeBase() && !base) {
      // fall back to whatever viewBox the file shipped with
      var svg = svgEl(), vb = svg && svg.viewBox && svg.viewBox.baseVal;
      if (!vb || !vb.width) return;
      base = { x: vb.x, y: vb.y, w: vb.width, h: vb.height };
    }
    if (!base) return;
    view = { x: base.x, y: base.y, w: base.w, h: base.h };
    applyView();
  }

  // client (px) -> user-space point, honouring preserveAspectRatio
  function toUser(svg, clientX, clientY, ctm) {
    var m = ctm || svg.getScreenCTM();
    if (!m) return null;
    var pt = svg.createSVGPoint();
    pt.x = clientX; pt.y = clientY;
    return pt.matrixTransform(m.inverse());
  }

  // zoom by `factor`, keeping the point under the cursor stationary
  function zoomAt(factor, clientX, clientY) {
    var svg = svgEl();
    if (!svg) return;
    if (!view) { fit(); if (!view) return; }
    var scale = base.w / view.w;                       // current magnification
    var target = Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, scale * factor));
    factor = target / scale;
    if (Math.abs(factor - 1) < 1e-4) return;

    var anchor;
    if (clientX == null) {                             // button zoom: centre
      anchor = { x: view.x + view.w / 2, y: view.y + view.h / 2 };
    } else {
      anchor = toUser(svg, clientX, clientY);
      if (!anchor) return;
    }
    var nw = view.w / factor, nh = view.h / factor;
    view = {
      x: anchor.x - (anchor.x - view.x) / factor,
      y: anchor.y - (anchor.y - view.y) / factor,
      w: nw, h: nh
    };
    applyView();
  }

  function bindStage() {
    var stage = document.querySelector(".snake-stage");
    var svg = svgEl();
    if (!stage || !svg || stage.dataset.snakeBound === "1") return;
    stage.dataset.snakeBound = "1";

    fit();

    // The Snakeplot tab is usually hidden on first load, so getBBox() cannot
    // measure yet and fit() falls back to the viewBox baked into the file.
    // Tighten it the moment the stage actually has a size.
    if (window.ResizeObserver) {
      new ResizeObserver(function () {
        if (!baseTight && computeBase()) fit();
      }).observe(stage);
    }

    stage.addEventListener("wheel", function (ev) {
      ev.preventDefault();
      zoomAt(Math.pow(1.0015, -ev.deltaY), ev.clientX, ev.clientY);
    }, { passive: false });

    stage.addEventListener("dblclick", function (ev) { ev.preventDefault(); fit(); });

    // drag to pan, two-finger pinch to zoom.  A drag must not register as a
    // residue click, and we only take pointer capture *after* movement starts:
    // capturing on pointerdown would retarget the click to the stage and break
    // click-to-select.
    var pointers = {};          // active pointerId -> {cx, cy}
    var drag = null;            // single-pointer pan state
    var pinch = null;           // two-pointer zoom state

    function pointerList() {
      return Object.keys(pointers).map(function (k) { return pointers[k]; });
    }
    function pinchDist(a, b) {
      return Math.hypot(a.cx - b.cx, a.cy - b.cy);
    }

    stage.addEventListener("pointerdown", function (ev) {
      if (ev.pointerType === "mouse" && ev.button !== 0) return;
      if (!view) return;
      pointers[ev.pointerId] = { cx: ev.clientX, cy: ev.clientY };
      var ps = pointerList();
      if (ps.length === 2) {
        drag = null;
        pinch = { dist: pinchDist(ps[0], ps[1]) };
        suppressClick = true;
      } else if (ps.length === 1) {
        var ctm = svg.getScreenCTM();
        var p = toUser(svg, ev.clientX, ev.clientY, ctm);
        if (!p) return;
        drag = { ctm: ctm, x0: p.x, y0: p.y, vx: view.x, vy: view.y,
                 cx: ev.clientX, cy: ev.clientY, moved: false, id: ev.pointerId };
      }
    });

    stage.addEventListener("pointermove", function (ev) {
      if (!pointers[ev.pointerId]) return;
      pointers[ev.pointerId] = { cx: ev.clientX, cy: ev.clientY };

      if (pinch) {
        var ps = pointerList();
        if (ps.length < 2) return;
        var d = pinchDist(ps[0], ps[1]);
        if (pinch.dist > 0 && d > 0) {
          zoomAt(d / pinch.dist, (ps[0].cx + ps[1].cx) / 2, (ps[0].cy + ps[1].cy) / 2);
        }
        pinch.dist = d;
        return;
      }

      if (!drag || drag.id !== ev.pointerId) return;
      if (!drag.moved) {
        if (Math.abs(ev.clientX - drag.cx) + Math.abs(ev.clientY - drag.cy) < 4) return;
        drag.moved = true;
        stage.style.cursor = "grabbing";
        try { stage.setPointerCapture(ev.pointerId); } catch (e) { /* no capture */ }
      }
      var p = toUser(svg, ev.clientX, ev.clientY, drag.ctm);
      if (!p) return;
      view.x = drag.vx - (p.x - drag.x0);
      view.y = drag.vy - (p.y - drag.y0);
      applyView();
    });

    function endDrag(ev) {
      delete pointers[ev.pointerId];
      if (pointerList().length < 2) pinch = null;
      if (drag && drag.id === ev.pointerId) {
        if (drag.moved) {
          suppressClick = true;
          try { stage.releasePointerCapture(ev.pointerId); } catch (e) { /* none */ }
        }
        drag = null;
        stage.style.cursor = "";
      }
    }
    stage.addEventListener("pointerup", endDrag);
    stage.addEventListener("pointercancel", endDrag);

    var btn = {
      snk_zoom_in:    function () { zoomAt(1.3); },
      snk_zoom_out:   function () { zoomAt(1 / 1.3); },
      snk_zoom_reset: fit
    };
    Object.keys(btn).forEach(function (id) {
      var b = document.getElementById(id);
      if (b) b.addEventListener("click", function (ev) { ev.preventDefault(); btn[id](); });
    });
  }

  // the SVG is inlined in the initial HTML, but the tab may render later
  var stageObserver = new MutationObserver(function () {
    bindStage();
    var st = document.querySelector(".snake-stage");
    if (st && st.dataset.snakeBound === "1") stageObserver.disconnect();
  });
  function initStage() {
    bindStage();
    if (document.querySelector('.snake-stage[data-snake-bound="1"]')) return;
    stageObserver.observe(document.body, { childList: true, subtree: true });
    window.addEventListener("resize", function () { if (!baseTight && computeBase()) fit(); });
  }
  if (document.readyState === "loading")
    document.addEventListener("DOMContentLoaded", initStage);
  else initStage();

  function registerHandlers() {
    if (!window.Shiny || !Shiny.addCustomMessageHandler) return false;

    // colour residues.
    // msg = {ids:[int], colors:[hex], values:[str], score_label:str, default_color:hex}
    Shiny.addCustomMessageHandler("snake_recolor", function (msg) {
      var def = msg.default_color || "#eeeeee";
      var ids = asArray(msg.ids), cols = asArray(msg.colors), vals = asArray(msg.values);
      scoreLabel = msg.score_label || "";
      valMap = {};
      ids.forEach(function (id, i) { valMap[id] = vals[i]; });
      var map = {};
      ids.forEach(function (id, i) { map[id] = cols[i]; });
      circles().forEach(function (c) {
        var id = parseInt(c.getAttribute("id"), 10);
        var col = map.hasOwnProperty(id) ? map[id] : def;
        c.setAttribute("fill", col);
        c.setAttribute("fill-opacity", "1");
        var t = textFor(id);
        if (t) t.setAttribute("fill", labelColor(col));
      });
    });

    // highlight the current selection.  msg = {ids:[int], color:hex}
    Shiny.addCustomMessageHandler("snake_highlight", function (msg) {
      var sel = {};
      asArray(msg.ids).forEach(function (id) { sel[id] = true; });
      var hl = msg.color || "#ff2d55";
      circles().forEach(function (c) {
        var id = parseInt(c.getAttribute("id"), 10);
        if (sel[id]) {
          c.setAttribute("stroke", hl);
          c.setAttribute("stroke-width", "5");
        } else {
          c.setAttribute("stroke", "black");
          c.setAttribute("stroke-width", "2");
        }
      });
    });

    return true;
  }

  if (!registerHandlers()) {
    document.addEventListener("shiny:connected", registerHandlers);
  }
})();
